package com.aetherforge.api;import com.aetherforge.security.TokenService;import com.aetherforge.service.EventStreamService;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1/events") public class RealtimeController {private final EventStreamService s;private final TokenService tokens;public RealtimeController(EventStreamService s,TokenService tokens){this.s=s;this.tokens=tokens;}@GetMapping(produces="text/event-stream") public SseEmitter stream(@RequestParam(name="access_token",required=false)String token){if(token==null||tokens.resolve(token)==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Session expired");return s.subscribe();}}
